Rules.InvariantScript:
If(IsMatch(Trim(txtBuscarInicio_m.Text), "\d{1,2}\.?\d{3}\.?\d{3}-[\dkK]"),
Set(varModoPD, "Préstamos"); Set(varRutPd, Trim(txtBuscarInicio_m.Text));
Set(varUsrTxt, IfError(Text('FolioUsuario'.Run(Trim(txtBuscarInicio_m.Text)).datos), "{}"));
Set(varUsr, ParseJSON(If(IsBlank(varUsrTxt), "{}", varUsrTxt))); If(IsBlank(varUsrTxt), Set(varUsrTxt, "{}"));
If(Text(varUsr.encontrado) = "SI", Set(varRutPd, Text(varUsr.rut)),
    Notify("No está en FOLIO: puede registrar igual con el RUT escrito.", NotificationType.Warning));
Navigate(PrestamosM, ScreenTransition.Fade),
With({q: Trim(txtBuscarInicio_m.Text)},
    If(Len(q) < 2,
        Notify("Escriba al menos 2 caracteres.", NotificationType.Information),
        With({ing: First(Filter(colIngresos, Text(Correlativo) = q || Lower(q) in Lower(Titulo) || Lower(q) in Lower(Autor) || q = Text('Numero inventario')))},
            If(!IsBlank(ing),
                Set(varSel, ing); Navigate(IngresomaterialM, ScreenTransition.Fade),
                q in colFicha.'Codigo de Barra',
                Notify("El código " & q & " ya está en la Ficha de Descarte.", NotificationType.Information),
                Set(varCodEj, q); Set(varEj, ParseJSON("{}")); Navigate(ConsultarEjemplarM, ScreenTransition.Fade)
            )
        )
    )
))

