If(IsBlank(Text(varResumen.fecha)),
    Set(varResumenTxt, IfError(Text('FolioResumenInicio'.Run().datos), ""));
    Set(varResumen, ParseJSON(If(IsBlank(varResumenTxt), "{}", varResumenTxt)));
    With({s: Split(Text(varResumen.serie), ";")},
        ClearCollect(colSerie,
            ForAll(Sequence(CountRows(s)),
                With({p: Split(Index(s, Value).Value, "|")},
                    {i: Value, d: First(p).Value, n: Value(Last(p).Value)}
                )
            )
        )
    )
);
With({a: Split(Text(varResumen.mes), ";"), b: Split(Text(varResumen.mesAnt), ";")},
    ClearCollect(colMes, ForAll(Filter(Sequence(CountRows(a)), !IsBlank(Index(a, Value).Value)), {i: Value, n: Value(Index(a, Value).Value)}));
    ClearCollect(colMesAnt, ForAll(Filter(Sequence(CountRows(b)), !IsBlank(Index(b, Value).Value)), {i: Value, n: Value(Index(b, Value).Value)})));
ClearCollect(colServ,
    {n: 1, rom: "II", lo: "Ingresos", nm: "Ingreso de material", est: "", tipo: "neu", kpi: Text(CountRows(Filter(colIngresos, Etapa = "En PPTT" || Etapa = "Recibido en PPTT" || Etapa = "Catalogado" || Etapa = "Marbete impreso")), "#,0", "es-CL"), kpil: "EN PPTT", msg: ""},
    {n: 2, rom: "III", lo: "Marbetes", nm: "Generador de marbetes", est: "", tipo: "neu", kpi: "—", kpil: "POR CÓDIGO", msg: ""},
    {n: 3, rom: "IV", lo: "Morosos", nm: "Cobranza de morosos", est: "", tipo: "neg", kpi: If(!IsBlank(Text(varResumen.fecha)), Text(Value(varResumen.morosos), "#,0", "es-CL"), "—"), kpil: "USUARIOS", msg: ""},
    {n: 4, rom: "V", lo: "Descarte", nm: "Descarte de títulos", est: "", tipo: "neu", kpi: Text(CountRows(colFicha), "#,0", "es-CL"), kpil: "EN LA FICHA", msg: ""},
    {n: 5, rom: "VI", lo: "Préstamos", nm: "Préstamos y devoluciones", est: "", tipo: "neu", kpi: If(!IsBlank(Text(varResumen.fecha)), Text(Value(varResumen.hoy), "#,0", "es-CL"), "—"), kpil: "ÚLTIMO DÍA", msg: ""},
    {n: 6, rom: "VII", lo: "Inventario", nm: "Inventario y revisión", est: "", tipo: "neu", kpi: "—", kpil: "POR ESTANTE", msg: ""}
